CREATE TABLE users (id BIGINT PRIMARY KEY, display_name VARCHAR(100) NOT NULL, created_at DATETIME(6) NOT NULL, deleted_at DATETIME(6) NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE user_sessions (id BIGINT PRIMARY KEY, user_id BIGINT NOT NULL, token_hash CHAR(64) NOT NULL, client_type VARCHAR(16) NOT NULL, expires_at DATETIME(6) NOT NULL, revoked_at DATETIME(6), created_at DATETIME(6) NOT NULL, UNIQUE KEY uk_session_token(token_hash), KEY ix_session_user(user_id,expires_at), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE tesla_accounts (id BIGINT PRIMARY KEY, user_id BIGINT NOT NULL, region VARCHAR(8) NOT NULL, tesla_subject VARCHAR(128), scopes VARCHAR(512) NOT NULL, authorization_state VARCHAR(20) NOT NULL, created_at DATETIME(6) NOT NULL, UNIQUE KEY uk_tesla_subject(region,tesla_subject), KEY ix_account_user(user_id), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE tesla_tokens (account_id BIGINT PRIMARY KEY, access_ciphertext TEXT NOT NULL, refresh_ciphertext TEXT NOT NULL, expires_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, FOREIGN KEY(account_id) REFERENCES tesla_accounts(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE vehicles (id BIGINT PRIMARY KEY, account_id BIGINT, vin VARCHAR(32) NOT NULL, display_name VARCHAR(100) NOT NULL, model VARCHAR(50), color VARCHAR(40), firmware VARCHAR(80), region VARCHAR(8) NOT NULL, key_state VARCHAR(20) NOT NULL DEFAULT 'UNKNOWN', created_at DATETIME(6) NOT NULL, UNIQUE KEY uk_vehicle_vin(vin), KEY ix_vehicle_account(account_id), FOREIGN KEY(account_id) REFERENCES tesla_accounts(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE vehicle_user_access (vehicle_id BIGINT NOT NULL, user_id BIGINT NOT NULL, access_level VARCHAR(20) NOT NULL, created_at DATETIME(6) NOT NULL, PRIMARY KEY(vehicle_id,user_id), KEY ix_access_user(user_id), FOREIGN KEY(vehicle_id) REFERENCES vehicles(id), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE vehicle_status_latest (vehicle_id BIGINT PRIMARY KEY, source VARCHAR(20) NOT NULL, observed_at DATETIME(6), received_at DATETIME(6), updated_at DATETIME(6) NOT NULL, online_state VARCHAR(20), soc DECIMAL(5,2), range_km DECIMAL(8,2), odometer_km DECIMAL(12,2), inside_c DECIMAL(5,2), outside_c DECIMAL(5,2), climate_on BOOLEAN, locked BOOLEAN, charging_state VARCHAR(32), charging_kw DECIMAL(8,2), charge_limit INT, latitude DECIMAL(10,7), longitude DECIMAL(10,7), data_json JSON, FOREIGN KEY(vehicle_id) REFERENCES vehicles(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE vehicle_telemetry_raw (id BIGINT PRIMARY KEY, vehicle_id BIGINT NOT NULL, event_key CHAR(64) NOT NULL, topic VARCHAR(160) NOT NULL, event_type VARCHAR(50) NOT NULL, observed_at DATETIME(6), received_at DATETIME(6) NOT NULL, payload JSON NOT NULL, UNIQUE KEY uk_raw_event(event_key), KEY ix_raw_vehicle_time(vehicle_id,received_at), FOREIGN KEY(vehicle_id) REFERENCES vehicles(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE vehicle_telemetry_samples (id BIGINT PRIMARY KEY, vehicle_id BIGINT NOT NULL, signal_name VARCHAR(64) NOT NULL, numeric_value DECIMAL(16,6), text_value VARCHAR(255), observed_at DATETIME(6) NOT NULL, received_at DATETIME(6) NOT NULL, source VARCHAR(20) NOT NULL, KEY ix_sample_vehicle_signal_time(vehicle_id,signal_name,observed_at), FOREIGN KEY(vehicle_id) REFERENCES vehicles(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE driving_trips (id BIGINT PRIMARY KEY, vehicle_id BIGINT NOT NULL, started_at DATETIME(6) NOT NULL, ended_at DATETIME(6), start_lat DECIMAL(10,7), start_lon DECIMAL(10,7), end_lat DECIMAL(10,7), end_lon DECIMAL(10,7), distance_km DECIMAL(10,3), energy_kwh DECIMAL(10,3), completeness VARCHAR(20) NOT NULL, KEY ix_trip_vehicle_start(vehicle_id,started_at), FOREIGN KEY(vehicle_id) REFERENCES vehicles(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE driving_trip_points (id BIGINT PRIMARY KEY, trip_id BIGINT NOT NULL, observed_at DATETIME(6) NOT NULL, latitude DECIMAL(10,7) NOT NULL, longitude DECIMAL(10,7) NOT NULL, speed_kmh DECIMAL(8,2), KEY ix_point_trip_time(trip_id,observed_at), FOREIGN KEY(trip_id) REFERENCES driving_trips(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE charging_sessions (id BIGINT PRIMARY KEY, vehicle_id BIGINT NOT NULL, started_at DATETIME(6) NOT NULL, ended_at DATETIME(6), start_soc DECIMAL(5,2), end_soc DECIMAL(5,2), grid_kwh DECIMAL(10,3), battery_kwh DECIMAL(10,3), estimated_kwh DECIMAL(10,3), estimated_cost DECIMAL(12,2), currency CHAR(3) NOT NULL DEFAULT 'CNY', KEY ix_charging_vehicle_start(vehicle_id,started_at), FOREIGN KEY(vehicle_id) REFERENCES vehicles(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE charging_tariffs (id BIGINT PRIMARY KEY, user_id BIGINT NOT NULL, name VARCHAR(80) NOT NULL, price_per_kwh DECIMAL(10,4) NOT NULL, starts_local TIME NOT NULL, ends_local TIME NOT NULL, timezone VARCHAR(64) NOT NULL, created_at DATETIME(6) NOT NULL, KEY ix_tariff_user(user_id), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE vehicle_command_logs (id BIGINT PRIMARY KEY, vehicle_id BIGINT NOT NULL, user_id BIGINT NOT NULL, idempotency_key VARCHAR(100) NOT NULL, command_type VARCHAR(50) NOT NULL, request_json JSON, outcome VARCHAR(20) NOT NULL, error_code VARCHAR(64), created_at DATETIME(6) NOT NULL, completed_at DATETIME(6), UNIQUE KEY uk_command_idempotency(user_id,vehicle_id,idempotency_key), KEY ix_command_vehicle_time(vehicle_id,created_at), FOREIGN KEY(vehicle_id) REFERENCES vehicles(id), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE notification_records (id BIGINT PRIMARY KEY, user_id BIGINT NOT NULL, vehicle_id BIGINT, type VARCHAR(40) NOT NULL, title VARCHAR(120) NOT NULL, body VARCHAR(500) NOT NULL, created_at DATETIME(6) NOT NULL, read_at DATETIME(6), KEY ix_notification_user_time(user_id,created_at), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE user_settings (user_id BIGINT PRIMARY KEY, retention_days INT NOT NULL DEFAULT 90, location_enabled BOOLEAN NOT NULL DEFAULT TRUE, sample_interval_seconds INT NOT NULL DEFAULT 60, updated_at DATETIME(6) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE oauth_states (state_hash CHAR(64) PRIMARY KEY, user_id BIGINT, nonce_hash CHAR(64) NOT NULL, client_type VARCHAR(16) NOT NULL, expires_at DATETIME(6) NOT NULL, consumed_at DATETIME(6), created_at DATETIME(6) NOT NULL, KEY ix_oauth_expiry(expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE telemetry_ingestion_offsets (consumer_name VARCHAR(80) NOT NULL, topic VARCHAR(160) NOT NULL, last_event_key CHAR(64), last_received_at DATETIME(6), updated_at DATETIME(6) NOT NULL, PRIMARY KEY(consumer_name,topic)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE automation_rules (id BIGINT PRIMARY KEY, user_id BIGINT NOT NULL, vehicle_id BIGINT, name VARCHAR(100) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT FALSE, definition_json JSON NOT NULL, created_at DATETIME(6) NOT NULL, KEY ix_rule_user(user_id), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE automation_execution_logs (id BIGINT PRIMARY KEY, rule_id BIGINT NOT NULL, outcome VARCHAR(20) NOT NULL, detail VARCHAR(500), created_at DATETIME(6) NOT NULL, KEY ix_execution_rule_time(rule_id,created_at), FOREIGN KEY(rule_id) REFERENCES automation_rules(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
